import * as OurCommon from "../src/common";

test("len('') gives 0: empty text", () => {
  expect(OurCommon.lenStr("")).toStrictEqual(0);
});

test("len('abc') gives 3: ASCII text", () => {
  expect(OurCommon.lenStr("abc")).toStrictEqual(3);
});

test("len('é-') gives 2: character of two UTF-8 bytes", () => {
  expect(OurCommon.lenStr("é-")).toStrictEqual(2);
});

test("len('😀-') gives 2: character beyond the Basic Multilingual Plane", () => {
  expect(OurCommon.lenStr("😀-")).toStrictEqual(2);
});

test("len('aé😀b😀') gives 5: mixed characters", () => {
  expect(OurCommon.lenStr("aé😀b😀")).toStrictEqual(5);
});

